head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getRunningWorkflow]<br/>현재 실행 중인 특정 Workflow 객체를 반환합니다.",
    "validation" : [
        "workflowId(선택) 파라미터로 조회할 Workflow 의 ID 를 설정할 수 있어야 합니다.",
        "workflowId(선택) 파라미터 생략 시 실행 중인 첫번째 Workflow 객체를 반환해야 합니다.",
        "실행 중인 Workflow 가 없으면 null 을 반환해야 합니다.",
        "실행이 진행되는 구간(pre, defaultCallback, callback, resolveCallback, rejectCallback 등) 에서만 Workflow 객체를 구할 수 있어야 합니다.",
        "완료된 Submission 들의 실행 결과 객체는 반환 객체의 workflowObj.result 로 접근할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// workflow step 의 마지막 function - 완료된 submission 결과(workflowObj.result) 접근 확인
scwin.wf_function_last = function () {
    var wf = $p.getRunningWorkflow();
    if (wf) {
        var resultKeys = wf.result ? Object.keys(wf.result) : [];
        wf_body_bottom.getObj("scwin").setReturnValue("[step] function - $p.getRunningWorkflow().result 의 키 목록 : [" + resultKeys.join(", ") + "]");
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("[step] function - $p.getRunningWorkflow() 반환값 : null");
    }
};

// submission pre - 실행 진행 구간에서 $p.getRunningWorkflow() 호출 확인
scwin.sbm_exam1_pre = function (submissionId, workflowObj) {
    var scenario = par_scenario.getValue();
    var wf;
    var wfType;
    var wfId;

    if (scenario === "1") {
        // 시나리오 1 : workflowId 파라미터 생략 → 실행 중인 첫번째 workflow 반환
        wf = $p.getRunningWorkflow();
        wfType = (wf === null) ? "null" : (typeof wf);
        wfId = wf ? wf.id : "-";
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] $p.getRunningWorkflow() (ID 생략) → 반환 타입 : " + wfType + " / id : " + wfId);
    } else if (scenario === "2") {
        // 시나리오 2 : workflowId 파라미터 지정 → 해당 ID 의 workflow 반환
        wf = $p.getRunningWorkflow("wf_exam1");
        wfType = (wf === null) ? "null" : (typeof wf);
        wfId = wf ? wf.id : "-";
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] $p.getRunningWorkflow('wf_exam1') → 반환 타입 : " + wfType + " / id : " + wfId);

        // 실행 중이지 않은 ID 를 조회하면 null 반환 확인
        var wfNone = $p.getRunningWorkflow("wf_not_running");
        var wfNoneType = (wfNone === null) ? "null" : (typeof wfNone);
        wf_body_bottom.getObj("scwin").setReturnValue("[pre] $p.getRunningWorkflow('wf_not_running') → 반환 타입 : " + wfNoneType);
    }

    return true;
};

scwin.sbm_exam1_post = function (submissionObj, workflowObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[post] sbm_exam1 응답 수신");
};

// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    // resolveCallback 구간에서도 $p.getRunningWorkflow() 호출 가능 확인
    var wf = $p.getRunningWorkflow();
    var wfId = wf ? wf.id : "null";
    wf_body_bottom.getObj("scwin").setReturnValue("[resolveCallback] $p.getRunningWorkflow().id : " + wfId + " → workflow 완료");
};

scwin.wf_rejectCallback = function (wObj) {
    wf_body_bottom.getObj("scwin").setReturnValue("[rejectCallback] workflow 오류");
};



scwin.btn_getRunningWorkflow_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : workflowId 파라미터 생략 → 실행 중인 첫번째 workflow 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : $p.getRunningWorkflow() (ID 생략) - 실행 중인 첫번째 Workflow 반환 ──");
        $p.executeWorkflow("wf_exam1");
    } else if (scenario === "2") {
        // 시나리오 2 : workflowId 파라미터 지정 → 해당 ID 의 workflow 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : $p.getRunningWorkflow('wf_exam1') - 특정 ID 로 Workflow 반환 ──");
        $p.executeWorkflow("wf_exam1");
    } else if (scenario === "3") {
        // 시나리오 3 : 실행 중 workflow 가 없을 때 → null 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 실행 중 Workflow 가 없을 때 호출 - null 반환 ──");
        var wf = $p.getRunningWorkflow();
        var wfType = (wf === null) ? "null" : (typeof wf);
        wf_body_bottom.getObj("scwin").setReturnValue("btn onclick 구간 $p.getRunningWorkflow() → 반환 타입 : " + wfType + " (실행 중 workflow 없음)");

        // 특정 ID 조회도 null
        var wfById = $p.getRunningWorkflow("wf_exam1");
        var wfByIdType = (wfById === null) ? "null" : (typeof wfById);
        wf_body_bottom.getObj("scwin").setReturnValue("btn onclick 구간 $p.getRunningWorkflow('wf_exam1') → 반환 타입 : " + wfByIdType);
    }
};
